const paths={tank:'M3 15h18l1 4-2 2H4l-2-2 1-4Z M6 15v-4h12v4 M9 11V7h7v4 M16 8h7 M6 18h.01 M10 18h.01 M14 18h.01 M18 18h.01',plane:'m12 2 2 8 8 5v2l-8-2v5l3 2H7l3-2v-5l-8 2v-2l8-5 2-8Z',coins:'M20 6c0 2-16 2-16 0s16-2 16 0Z M4 6v5c0 2 16 2 16 0V6 M4 11v5c0 2 16 2 16 0v-5 M4 16v4c0 2 16 2 16 0v-4',factory:'M3 21V10l6 3V9l7 4V4h4v17H3Z M6 17h2 M11 17h2 M16 17h2',shield:'m12 2 9 4v6c0 5-9 10-9 10S3 17 3 12V6l9-4Z m-4 10 3 3 5-6',peace:'m2 11 4-5 5 2 3-2 8 5-4 8-4 2-8-5-4-5Z M7 10l4-2 4 5-2 2-3-2 M14 16l3 2 M10 18l3 2',troops:'M8 7a3 3 0 1 0 0-6 3 3 0 0 0 0 6 M16 10a3 3 0 1 0 0-6 3 3 0 0 0 0 6 M2 20v-6c0-6 12-6 12 0v6 M14 12c4-2 8 0 8 4v4 M6 15v6 M10 15v6',flag:'M5 22V3 M5 3c5-5 9 5 15 0v10c-6 5-10-5-15 0',map:'m2 5 7-3 6 3 7-3v17l-7 3-6-3-7 3V5Z M9 2v17 M15 5v17',sound:'m11 3-6 5H2v8h3l6 5V3Z M15 8c3 2 3 6 0 8 M18 4c6 4 6 12 0 16',mute:'m11 3-6 5H2v8h3l6 5V3Z m5 5 6 8 m0-8-6 8',settings:'M4 6h16 M4 12h16 M4 18h16 M8 3v6 M16 9v6 M10 15v6',arrow:'M4 12h16 m-6-6 6 6-6 6',globe:'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0Z M2 12h20 M12 2c6 6 6 14 0 20-6-6-6-14 0-20Z',trade:'M3 7h17l-5-5 M21 17H4l5 5',star:'m12 2 3 6 7 1-5 5 1 8-6-4-6 4 1-8-5-5 7-1 3-6Z',book:'M12 5C7 1 2 3 2 3v17s5-2 10 2c5-4 10-2 10-2V3s-5-2-10 2Zm0 0v17',check:'m4 12 5 5L20 6',pause:'M8 4v16 M16 4v16'};
Object.assign(paths,EVENT_PATHS);
const icon=name=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.flag}"/></svg>`;
let map,state=null,mode='menu',selected='CHL',difficulty='explorer',tab='actions',stance='peace',source='',busy=false,tip=true,resultShown=false,sound=false,low=false,audio=null,saveWarned=false;
let modalKind='',aiTimer=null,noticeTimer=null,spinTimer=null,autoWatch=true,skipReport=false,gameEpoch=0;
let turnViewKey='',turnTravelling=false,followCamera=true,stepByStep=true;
let operationChoice=null,bombSource='';
