const factionLabel=id=>esc(factionName(state,id));
const interfaceState=new InterfaceState(),compactMedia=matchMedia(COMPACT_QUERY),isCompact=()=>compactMedia.matches;
let renderedCountry='',renderedPhase='';
function readSave(){try{const raw=JSON.parse(localStorage.getItem(SAVE_KEY));const s=upgradeSave(raw);if(s&&raw.version<4&&!localStorage.getItem(SAVE_BACKUP_KEY))localStorage.setItem(SAVE_BACKUP_KEY,JSON.stringify(raw));return s;}catch{return null;}}
let saved=readSave();try{const p=JSON.parse(localStorage.getItem('dominio-settings')||'{}');sound=p.sound===true;low=p.low===true;followCamera=p.followCamera!==false;stepByStep=p.pace!=='auto';}catch{}
function save(){if(!state)return;try{localStorage.setItem(SAVE_KEY,JSON.stringify(state));saved=state;}catch{if(!saveWarned){toast('No pudimos guardar. Mantén esta pestaña abierta para seguir jugando.');saveWarned=true;}}}
function saveSettings(){try{localStorage.setItem('dominio-settings',JSON.stringify({sound,low,followCamera,pace:stepByStep?'step':'auto'}));}catch{}}
function tone(kind='click'){if(!sound)return;try{audio??=new (window.AudioContext||window.webkitAudioContext)();audio.resume();const start=audio.currentTime,notes=kind==='win'?[330,440,660]:kind==='turn'?[220,330]:kind==='bad'?[160,120]:[440];notes.forEach((f,i)=>{const o=audio.createOscillator(),g=audio.createGain();o.type='sine';o.frequency.value=f;g.gain.setValueAtTime(0,start+i*.1);g.gain.linearRampToValueAtTime(.035,start+i*.1+.015);g.gain.exponentialRampToValueAtTime(.001,start+i*.1+.25);o.connect(g);g.connect(audio.destination);o.start(start+i*.1);o.stop(start+i*.1+.3);});}catch{}}
let toastTimer;function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4200);}
function stopAI(){clearTimeout(aiTimer);aiTimer=null;}
let focusBeforeModal;
function modal(content,wide=false,kind='user'){stopAI();clearTimeout(noticeTimer);if(!$('#modalRoot').firstChild)focusBeforeModal=document.activeElement;modalKind=kind;document.body.classList.add('has-modal');$('#modalRoot').innerHTML=`<div class="modal-backdrop"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-label="Ventana de juego">${content}</section></div>`;$('#modalRoot').querySelector('button,select,a')?.focus();}
function dismiss(){stopAI();clearTimeout(noticeTimer);modalKind='';document.body.classList.remove('has-modal');$('#modalRoot').innerHTML='';}
function closeModal(){if(['notice','incident','report','event','draw','result','battleBriefing','turnStep'].includes(modalKind))return;dismiss();focusBeforeModal?.focus?.();render();}
const close='<button class="modal-close" data-ui="close" aria-label="Cerrar">×</button>';
function selectCountry(id,{openPanel=false}={}){if(!BY_ID[id]||busy||interfaceState.hidden)return;selected=id;tab='actions';source='';if(isCompact()){if(openPanel)interfaceState.showPanel();else interfaceState.closePanel();}map?.select(id);if(mode==='menu')return;render();map?.focusCountry(id);tone();}
function canAct(){return state&&isPlayerTurn(state)&&!state.event&&!state.inbox.length&&!state.pendingBattle&&!state.pendingOccupation&&!busy&&!interfaceState.hidden;}
function render(){
 const scroll=selected===renderedCountry&&state?.phase===renderedPhase?$('.panel-scroll')?.scrollTop||0:0;
 stopAI();if(mode==='menu')interfaceState.reset();document.body.dataset.mode=mode;document.body.dataset.phase=mode==='play'?state.phase:'';applyInterfaceState();
 setFactionFlags(mode==='play'?state:null);map?.setMode(mode);map?.sync(mode==='play'?(state.pendingBattle?{...state,countries:state.pendingBattle.beforeCountries}:state):null);map?.select(selected);
 $('#soundBtn').innerHTML=icon(sound?'sound':'mute');$('#soundBtn').setAttribute('aria-label',sound?'Silenciar sonido':'Activar sonido');$('#settingsBtn').innerHTML=icon('settings');
 $('#topCenter').innerHTML=mode==='play'?hud():`<span class="top-caption">${mode==='choose'?'ELIGE TU BANDERA':''}</span>`;
 $('#ui').innerHTML=(mode==='menu'?menu():mode==='choose'?choose():play())+(mode!=='menu'?mobileHUD():'');
 const panelScroll=$('.panel-scroll');if(panelScroll)panelScroll.scrollTop=scroll;renderedCountry=selected;renderedPhase=state?.phase;map?.resize();updateMapControls();
 if(mode==='play'){
  const rail=$('.queue-scroll'),current=$('.queue-item.current');if(rail&&current)rail.scrollLeft=Math.max(0,current.offsetLeft-rail.clientWidth*.3);
  present();
 }
}
function present(){
 if(modalKind||busy||mode!=='play'||map?.isInteracting||interfaceState.hidden)return;
 if(state.phase==='draw'||state.phase==='ready'){drawModal();return;}
 if(state.pendingOccupation&&!state.pendingBattle){const notice=state.notifications.find(n=>n.id===state.pendingOccupation.noticeId);if(notice&&!notice.read){noticeModal();return;}playScene();return;}
 if(state.fastForward&&!state.pendingBattle&&!state.inbox.length){advanceSkip();return;}
 if(state.status==='playing'&&['player','ai'].includes(state.phase)&&turnViewKey!==turnKey()){if(!skipReport&&pendingNotices(state)[0]?.kind==='endturn'){noticeModal();return;}turnViewKey=turnKey();const wasOpen=interfaceState.panelOpen;interfaceState.closePanel();applyInterfaceState();map?.resize();if(followCamera){travelToTurn();return;}if(wasOpen){render();return;}}
 if(state.pendingBattle){
  // Declarations precede combat; results do not exist until the scene finishes.
  if(state.inbox.length&&state.pendingBattle.resolution){if(['incidentStart','incidentEnd'].includes(pendingNotices(state)[0]?.kind))incidentNotice();else noticeModal();return;}
  if(state.pendingBattle.stage==='briefing'){if(state.fastForward){beginBattle(state);save();}else{battleBriefing();return;}}
  playScene();return;
 }
 if(state.movements.length){playScene();return;}
 if(state.inbox.length){if(skipReport)reportModal();else if(['incidentStart','incidentEnd'].includes(pendingNotices(state)[0]?.kind))incidentNotice();else noticeModal();return;}
 skipReport=false;
 if(state.status!=='playing'){if(!resultShown){resultShown=true;resultModal();}return;}
 if(state.event){eventModal();return;}
 if(state.phase==='ai'&&autoWatch&&!(isCompact()&&interfaceState.panelOpen)){if(stepByStep){turnStep();return;}const epoch=gameEpoch;aiTimer=setTimeout(()=>{if(epoch!==gameEpoch||mode!=='play'||modalKind||interfaceState.hidden)return;nextRival();},state.aiReport?2800:2400);}
}
function applyInterfaceState(){
 document.body.classList.toggle('interface-hidden',interfaceState.hidden);document.body.classList.toggle('panel-open',interfaceState.panelOpen);document.body.classList.toggle('has-modal',!!modalKind);
 const button=$('#interfaceToggle'),pending=interfaceState.hidden&&mode==='play'?state?.inbox.length||0:0;
 button.innerHTML=`${icon('map')}<span>${interfaceState.hidden?'VER INTERFAZ':'SOLO MAPA'}</span>${pending?`<b class="pending-count">${pending}</b>`:''}`;button.setAttribute('aria-pressed',String(interfaceState.hidden));button.setAttribute('aria-label',interfaceState.hidden?`Mostrar interfaz${pending?` · ${pending} avisos pendientes`:''}`:'Ocultar toda la interfaz');
 $('#ui').inert=interfaceState.hidden;$('#topbar').inert=interfaceState.hidden;$('#mapTools').inert=interfaceState.hidden;
}
function toggleInterface(){if(modalKind||mode==='menu')return;stopAI();interfaceState.toggleMap();render();if(!modalKind)$('#interfaceToggle').focus({preventScroll:true});}
function openCountryPanel(){if(busy||interfaceState.hidden)return;interfaceState.showPanel();render();if(!modalKind&&isCompact())$('.sheet-toolbar button')?.focus({preventScroll:true});}
function closeCountryPanel(){interfaceState.closePanel();render();if(!modalKind)$('.mobile-country-bar')?.focus({preventScroll:true});}
function sheetToolbar(){return '<div class="sheet-toolbar"><span>PAÍS Y ACCIONES</span><button data-ui="closePanel" aria-label="Cerrar panel y ver mapa">VER MAPA <span aria-hidden="true">⌄</span></button></div>';}
function mobileHUD(){
 const choosing=mode==='choose',spectator=!choosing&&state.phase==='ai',faction=!choosing?currentFaction(state):null,id=spectator?turnFocusId(state,faction)||selected:selected,c=BY_ID[id],sc=!choosing?state.countries[id]:null;
 const detail=choosing?`${c.population.toLocaleString('es-CL',{maximumFractionDigits:1})} M habitantes · Conocer país`:spectator?'Ver sus decisiones y controles':`${sc.troops} unidades · ${sc.owner===state.player?'Tu territorio':factionLabel(sc.owner)}`;
 const label=choosing?'VER PAÍS':spectator?'VER TURNO':'ACCIONES';
 const primary=choosing?(interfaceState.panelOpen?`<button class="primary" data-ui="start">ELEGIR ${c.name.toUpperCase()} ${icon('arrow')}</button>`:'<button class="primary" data-ui="openPanel">CONOCER Y ELEGIR</button>'):spectator?`<button class="primary" data-ui="skipAll" ${busy?'disabled':''}><span>IR A MI TURNO<small>Verás si atacan tus países</small></span>${icon('arrow')}</button>`:`<button class="primary" data-ui="endturn" ${!isPlayerTurn(state)||busy?'disabled':''}><span>TERMINAR TURNO<small>${state.status!=='playing'?'Campaña terminada':`${state.ap} de 3 acciones disponibles`}</small></span>${icon('arrow')}</button>`;
 return `<div class="mobile-hud">${!choosing&&faction?`<button class="mobile-turn-bar" data-ui="order" aria-label="Ver orden de turnos">${flag(faction)}<span><strong>${faction===state.player?'TU TURNO':`JUEGA ${factionLabel(faction).toUpperCase()}`}</strong><small>${dateLabel(state)} · Ronda ${state.turn}</small></span><b>${faction===state.player?`${state.ap} / 3 ★`:autoWatch&&!(isCompact()&&interfaceState.panelOpen)?'OBSERVANDO':'EN PAUSA'}</b>${icon('arrow')}</button>`:''}<button class="mobile-country-bar" data-ui="openPanel" aria-expanded="${interfaceState.panelOpen}" aria-controls="countryPanel">${flag(id)}<span><strong>${c.name}</strong><small>${detail}</small></span><b>${label} ${icon('arrow')}</b></button><nav class="mobile-bottom-nav" aria-label="Controles de la partida"><button data-ui="nations">${icon('flag')}PAÍSES</button><button data-ui="${choosing?'help':'mobileNews'}">${icon(choosing?'book':'globe')}${choosing?'AYUDA':`NOTICIAS <span class="news-dot">${activeIncidents(state).length} sucesos</span>`}</button>${primary}</nav></div>`;
}
function mobileNews(){modal(`${close}<button class="secondary" data-ui="calendar">${dateLabel(state)} · CALENDARIO</button><div class="eyebrow">TODO LO QUE PASA</div><h2>NOTICIAS.</h2><div class="camera-options">${state.campaignMode==='factions'?'<button class="secondary" data-ui="factions">VER FACCIONES</button>':''}<button class="secondary" data-ui="incidents">${icon('globe')} SUCESOS ACTIVOS · ${activeIncidents(state).length}</button><button class="secondary" data-ui="territories">${icon('flag')} COLORES Y TERRITORIOS</button><button class="secondary" data-ui="worldStatus">${icon('peace')} GUERRA Y PAZ · ${liveWars(state).length} CONFLICTOS</button><button class="secondary" data-ui="convoys">${icon('troops')} CONVOYES · ${state.transfers.length}</button><button class="secondary" data-ui="journal">${icon('book')} TODAS LAS NOTICIAS</button></div><button class="primary" data-ui="close">VOLVER AL MAPA</button>`);}
function cameraModal(){modal(`${close}<div class="eyebrow">MUEVE EL CONTINENTE</div><h2>CÁMARA.</h2><p>Un dedo mueve. Dos dedos hacen zoom.</p><div class="camera-options"><button class="secondary" data-map="focus">${icon('flag')} CENTRAR PAÍS ${mode==='play'?'DEL TURNO':''}</button><button class="secondary" data-map="reset">${icon('globe')} VER TODO EL CONTINENTE</button><button class="secondary" data-map="orbit">${icon('map')} ${map.navigationMode==='orbit'?'VOLVER A DESPLAZAR':'ACTIVAR GIRO CON UN DEDO'}</button></div><button class="primary" data-ui="close">VOLVER</button>`,false,'camera');}
const turnKey=()=>state?`${state.turn}:${state.turnIndex}:${currentFaction(state)}`:'';
async function travelToTurn(){
 const faction=currentFaction(state),id=turnFocusId(state,faction);if(!id){render();return;}
 const epoch=gameEpoch;turnTravelling=true;busy=true;stopAI();selected=id;source='';render();document.body.classList.add('turn-travelling');
 $('#turnTravel').innerHTML=`<div class="turn-travel-card">${flag(faction)}<div><small>RONDA ${state.turn} · ${faction===state.player?'TE TOCA JUGAR':'JUEGA AHORA'}</small><strong>${factionLabel(faction)}</strong>${id!==faction?`<span>Desde ${BY_ID[id].name}</span>`:''}</div><button data-ui="skipTravel" aria-label="Omitir viaje de cámara">OMITIR ${icon('arrow')}</button></div>`;
 try{await map.focusCountry(id);}finally{if(epoch===gameEpoch){turnTravelling=false;busy=false;document.body.classList.remove('turn-travelling');$('#turnTravel').innerHTML='';render();}}
}
function updateMapControls(){
 if(!map?.navigation)return;const distance=map.navigation.flight?.kind==='zoom'?map.navigation.flight.endDistance:map.navigation.distance;
 $('#zoomValue').textContent=`${map.navigation.zoom.toFixed(1)}×`;
 $('[data-map="in"]').disabled=distance<=NAV_LIMITS.min+.02;$('[data-map="out"]').disabled=distance>=NAV_LIMITS.max-.02;
 const rotating=map.navigationMode==='orbit',button=$('#orbitBtn');button.setAttribute('aria-pressed',String(rotating));button.setAttribute('aria-label',rotating?'Volver a desplazar el mapa':'Activar giro del mapa');button.title=rotating?'Volver a mover el mapa':'Girar el mapa';
 $('#mapHint').textContent=isCompact()?(rotating?'1 DEDO: GIRAR · 2 DEDOS: ZOOM':'1 DEDO: MOVER · 2 DEDOS: ZOOM'):(rotating?'ARRASTRA PARA GIRAR · RUEDA PARA ACERCAR':'ARRASTRA PARA MOVER · RUEDA PARA ACERCAR · CLIC DERECHO PARA GIRAR');
}
function handleMapControl(type){const cameraMenu=modalKind==='camera';if(cameraMenu)dismiss();if(type==='reset')map.reset();else if(type==='focus'){const id=mode==='play'?turnFocusId(state,currentFaction(state))||selected:selected;selected=id;tab='actions';source='';render();map.focusCountry(id);}else if(type==='orbit'){map.navigation.cancel();map.setNavigationMode(map.navigationMode==='pan'?'orbit':'pan');}else map.zoom(type==='in'?.8:1.25);if(cameraMenu&&type!=='focus')render();updateMapControls();}
function menu(){return `<section class="hero"><div class="eyebrow">UN CONTINENTE. TU ESTRATEGIA.</div><h1 class="game-title" aria-label="DOMINIO — Last Frontier: Latinoamérica"><span class="game-title-name">DOMINIO</span><span class="game-title-subtitle">Last Frontier:</span><span class="game-title-edition">Latinoamérica</span></h1><p>Elige una bandera.<br>¡Haz crecer tu nación!</p><div class="hero-actions"><button class="primary" data-ui="new">NUEVA CAMPAÑA ${icon('arrow')}</button>${saved?`<button class="secondary" data-ui="continue">CONTINUAR · RONDA ${saved.turn}</button>`:''}<a class="secondary online-menu-link" href="./online.html">${icon('globe')} JUGAR EN LÍNEA <small>HASTA 20 JUGADORES</small></a><button class="secondary" data-ui="help">${icon('book')} CÓMO JUGAR</button><button class="text-btn" data-ui="credits">Una idea de Ian · Nuestro equipo</button></div></section><div class="menu-foot"><b>20 PAÍSES · 3 ACCIONES · TÚ DECIDES</b><br>Mejora, negocia o conquista.</div><div class="edition-stamp">EDICIÓN 1.8<b>UN MUNDO.<br>EN MOVIMIENTO.</b><span>ELIGE TU PRÓXIMO MOVIMIENTO</span></div>`;}
function realData(c){return `<div class="real-data"><div class="section-label">CONOCE EL PAÍS · 2024</div><p>Población aprox.<b>${c.population.toLocaleString('es-CL',{maximumFractionDigits:1})} millones</b></p><p>Personal militar¹<b>${c.personnel===null?'Sin dato comparable':c.personnel===0?'Sin ejército permanente':fmt(c.personnel)}</b></p><p class="fineprint">¹ Referencia histórica de RESDAL. Las fuerzas del juego son ficticias.</p><button class="text-btn" data-ui="sources" style="padding:3px 0">Fuentes y detalles ↗</button></div>`;}
function stats(c,sc){return `<div class="stat-grid"><div class="stat"><span class="stat-name">Poder</span><strong>${icon('tank')}${state&&mode==='play'?effectivePower(state,sc):power(sc)}</strong><small>puntos de juego</small></div><div class="stat"><span class="stat-name">Unidades</span><strong>${icon('troops')}${sc.troops}</strong><small>listas para jugar</small></div><div class="stat"><span class="stat-name">Industria</span><strong>${icon('factory')}Nv. ${sc.industry}</strong><small>+${state&&mode==='play'?countryIncome(state,sc):income(sc)} cr / ronda</small></div><div class="stat"><span class="stat-name">Aviones</span><strong>${icon('plane')}Nv. ${sc.air}</strong><small>${sc.air>=2?'alcance continental':'alcance regional'}</small></div></div>`;}
function choose(){const c=BY_ID[selected],preview={...c,troops:c.troops+LEVELS[difficulty].boost,fort:0};return `<section class="side-panel" id="countryPanel">${sheetToolbar()}<div class="panel-scroll"><div class="panel-kicker"><span>ELIGE TU PAÍS</span><span>20 BANDERAS</span></div><div class="country-heading">${flag(c.id,'country-flag')}<div><h2>${c.name}</h2><p>${c.capital}</p></div></div><p class="country-tip">${c.tip}</p>${factionSetupView(selected,campaignOptions,icon)}${stats(c,preview)}<div class="divider"></div><div class="stat"><span class="stat-name">Dinero inicial</span><strong>${icon('coins')}230 <small>créditos</small></strong></div>${realData(c)}</div><div class="panel-bottom"><div class="difficulty-selector">${Object.entries(LEVELS).map(([k,v])=>`<button data-difficulty="${k}" class="${difficulty===k?'active':''}">${v.label}</button>`).join('')}</div><p class="difficulty-note">${{explorer:'Para aprender y divertirse.',normal:'Los rivales dan más pelea.',hard:'Un reto para expertos.'}[difficulty]}</p><button class="primary" data-ui="start">ELEGIR ${c.name} ${icon('arrow')}</button><p class="player-note">La ruleta decide quién empieza.</p></div></section><aside class="setup-card"><div class="eyebrow">ASÍ DE FÁCIL</div><h3>ELIGE.<br>JUEGA.<br>CONQUISTA.</h3><div class="setup-step"><b>1</b><div>Elige tu bandera.</div></div><div class="setup-step"><b>2</b><div>Gira la ruleta.</div></div><div class="setup-step"><b>3</b><div>En tu turno, usa 3 acciones.<small>No tienes que atacar.</small></div></div><button class="text-btn" data-ui="menu">← Volver</button></aside><nav class="country-tray" aria-label="Elegir nación">${COUNTRIES.map(n=>`<button data-country="${n.id}" class="country-chip ${n.id===selected?'active':''}">${flag(n.id)}${n.name}</button>`).join('')}</nav>`;}
function hud(){return `<button class="calendar-chip" data-ui="calendar"><small>RONDA ${state.turn}</small><b>${dateLabel(state)}</b></button><div class="hud-stat">${icon('coins')}<div><small>CRÉDITOS</small><strong>${fmt(state.cash)}</strong><em>+${totalIncome(state)} / ronda</em></div></div><button class="hud-stat territory-key" data-ui="territories" title="Ver los colores y territorios de cada nación" style="--territory-color:${factionColor(state,state.player)}"><i class="territory-swatch"></i><div><small>PAÍSES</small><strong>${owned(state).length}<em>/ 20</em></strong></div></button><div class="hud-stat actions"><div><small>${isPlayerTurn(state)?'TUS ACCIONES':'ESPERANDO TURNO'}</small><div class="ap-dots">${[0,1,2].map(i=>`<i class="${i>=state.ap?'empty':''}"></i>`).join('')}</div></div></div>`;}
function queueBar(){if(!state.turnOrder.length)return '';const alive=activeFactions(state),id=currentFaction(state);return `<nav class="turn-queue" aria-label="Orden de turnos"><button class="round-label" data-ui="order"><small>RONDA</small><strong>${String(state.turn).padStart(2,'0')}</strong></button><div class="queue-scroll">${state.turnOrder.map((o,i)=>`<button class="queue-item ${i===state.turnIndex?'current':''} ${i<state.turnIndex?'played':''} ${!alive.includes(o.id)?'eliminated':''} ${o.id===state.player?'is-you':''}" data-country="${o.id}" title="${factionLabel(o.id)} · ${o.power} poder al inicio de ronda"><span class="queue-position">${i===state.turnIndex?'AHORA':i<state.turnIndex?'✓':i+1}</span>${flag(o.id)}<span>${o.id===state.player?'TÚ':factionLabel(o.id)}</span></button>`).join('')}</div><button class="queue-explain" data-ui="order" aria-label="Ver orden y regla de turnos">${icon('book')}<span>VER ORDEN</span></button></nav>`;}
function actionBank(){return `<div class="action-bank"><div class="action-bank-title"><b>${state.ap} de 3 acciones</b><button data-ui="actionsHelp" aria-label="Cómo usar las tres acciones">?</button></div><div class="action-tokens">${[0,1,2].map(i=>{const spent=state.spent[i];return `<span class="action-token ${spent?'spent':''}" title="${spent?UPGRADE[spent.type]?.name||'Acción usada':'Acción disponible'}">${spent?icon('check'):'★'}<small>${i+1}</small></span>`;}).join('')}<span class="action-free">Úsalas como quieras.<br><b>Atacar es opcional.</b></span></div></div>`;}
function play(){
 const spectator=state.phase==='ai',c=BY_ID[selected],sc=state.countries[selected],isOwn=sc.owner===state.player,n=owned(state).length;
 return `${queueBar()}${newsTicker()}${spectator?spectatorPanel():`<section class="side-panel" id="countryPanel">${sheetToolbar()}<div class="panel-scroll"><div class="panel-kicker"><span>${isOwn?'TU PAÍS':'OTRO PAÍS'}</span><span>${isPlayerTurn(state)?'TE TOCA JUGAR':'CAMPAÑA'}</span></div><div class="country-heading">${flag(c.id,'country-flag')}<div><h2>${c.name}</h2><p>${c.capital}</p></div></div><button class="tag territorial-tag ${isOwn?'':'neutral'}" data-ui="territories" style="--territory-color:${factionColor(state,sc.owner)}"><i class="territory-swatch"></i>CONTROL: ${factionLabel(sc.owner)}${isOwn?' · TÚ':''}</button>${isPlayerTurn(state)?actionBank():''}<div class="tabs"><button data-tab="actions" class="${tab==='actions'?'active':''}">${isOwn?'MEJORAR':'VISITAR'}</button><button data-tab="info" class="${tab==='info'?'active':''}">CONOCER</button></div>${countryIncident(sc.id)}${industryStatus(sc.id)}${tab==='info'?`${stats(c,sc)}${realData(c)}`:isOwn?development(sc):foreign(sc)}</div><div class="panel-bottom"><button class="secondary" data-ui="nations">${icon('map')} ELEGIR UN PAÍS</button></div></section>`}<aside class="mission-panel"><div class="eyebrow">TU MISIÓN</div><h3>REÚNE LAS<br>20 BANDERAS.</h3><div class="progress-count">${String(n).padStart(2,'0')} <span>/ 20</span></div><div class="progress-track">${Array.from({length:20},(_,i)=>`<i class="${i<n?'done':''}"></i>`).join('')}</div><p>Con acuerdos o conquistas.<br>Tú eliges el camino.</p><div class="section-label" style="margin-top:24px">QUÉ ESTÁ PASANDO</div>${state.log.slice(0,3).map(l=>`<div class="news-item"><small>RONDA ${l.turn}</small>${esc(l.text)}</div>`).join('')}<button class="text-btn" data-ui="calendar">${icon('globe')} CALENDARIO</button>${state.campaignMode==='factions'?'<button class="text-btn" data-ui="factions">VER FACCIONES</button>':''}<button class="text-btn" data-ui="journal">${icon('book')} VER NOTICIAS</button></aside><div class="bottom-dock"><button class="dock-nations" data-ui="home" style="border-left:4px solid ${factionColor(state,state.player)};padding-left:12px">${flag(state.player)}<span>${factionLabel(state.player).toUpperCase()}<small>Tu nación</small></span></button><div class="turn-summary"><strong>${spectator?`JUEGA ${factionLabel(currentFaction(state)).toUpperCase()}`:state.status!=='playing'?'FIN DE CAMPAÑA':'ES TU TURNO'}</strong>${spectator?'Puedes observar o saltar.':state.ap>0?`Tienes <b>${state.ap} acciones</b> para elegir.`:'Pulsa terminar para continuar.'}</div>${state.status!=='playing'?'<button class="primary end-turn" data-ui="menu">VOLVER AL MENÚ →</button>':spectator?`<button class="primary end-turn" data-ui="skipAll">IR A MI TURNO ${icon('arrow')}</button>`:`<button class="primary end-turn ${state.ap===0?'ready-turn':''}" data-ui="endturn" ${!isPlayerTurn(state)||busy?'disabled':''}>TERMINAR TURNO ${icon('arrow')}</button>`}</div>${tip&&isPlayerTurn(state)&&state.turn<=2?`<div class="tutorial-tip"><button data-ui="hidetip" aria-label="Ocultar consejo">×</button><b>¡Puedes jugar sin atacar!</b>Prueba mejorar la industria, reclutar y defender.</div>`:''}`;
}
function spectatorPanel(){const id=currentFaction(state),r=state.aiReport;return `<section class="side-panel spectator-panel" id="countryPanel">${sheetToolbar()}<div class="panel-scroll"><div class="panel-kicker"><span>ESTÁS OBSERVANDO</span><span>${autoWatch&&!(isCompact()&&interfaceState.panelOpen)?'▶ AUTOMÁTICO':'Ⅱ EN PAUSA'}</span></div>${flag(id,'spectator-flag')}<h2>JUEGA<br>${BY_ID[id].name.toUpperCase()}.</h2><div class="spectator-actions">${r?r.actions.map(a=>`<div>${icon(a.icon)}<span>${esc(a.text)}</span></div>`).join(''):`<div class="thinking"><i></i> Está eligiendo sus acciones…</div>`}</div><p class="fineprint">Las decisiones importantes aparecerán en un aviso.</p></div><div class="panel-bottom"><div class="spectator-buttons"><button class="secondary" data-ui="pauseWatch">${icon(autoWatch?'pause':'arrow')}${autoWatch?'PAUSAR':'SEGUIR'}</button><button class="secondary" data-ui="nextRival">${r?'SIGUIENTE':'VER ACCIONES'}</button></div><button class="text-btn" data-ui="skipOne">Saltar este país</button><button class="primary" data-ui="skipAll">SALTAR HASTA MI TURNO ${icon('arrow')}</button><p class="player-note">Verás si atacan tus países.</p></div></section>`;}
function pips(n){return `<span class="level-pips">${[1,2,3,4].map(i=>`<i class="${i<=n?'on':''}"></i>`).join('')}</span>`;}
function actionButton(type,title,desc,ic='peace',disabled=false){const price=cost(state,type,selected),block=upgradeBlock(state,type==='bombers'?'air':type,selected);if(block){disabled=true;desc=`${INCIDENTS[block.event.kind].title} · hasta R${block.event.until}`;}return `<button class="upgrade-card ${block?'event-blocked':''}" data-action="${type}" ${disabled||!canAct()||state.ap<1||state.cash<price?'disabled':''}><span class="upgrade-icon">${icon(ic)}</span><span class="upgrade-copy"><b>${title}</b><small>${desc}</small></span><span class="price">${type==='trade'?'+20':price}<small>${block?'EN PAUSA':'★ 1 ACCIÓN'}</small></span></button>`;}
function development(c){const defs={recruit:['Reclutar',`+${recruitAmount(state,c.id)} unidades${condition(state,c.id).recruit?' · por el suceso':''}`,'troops'],armor:['Tanques',`${map.vehicleName('tank',c.id,Math.min(4,c.armor+1))} · +28% fuerza`,'tank'],air:['Aviones',`${map.vehicleName('jet',c.id,Math.min(4,c.air+1))} · más fuerza`,'plane'],industry:['Industria','+12 créditos en cada ronda','factory'],fort:['Defender','Más protección: +20% por nivel','shield']};return `<div class="relation-row"><span>${icon('tank')} Poder ${effectivePower(state,c)}</span><span>${c.troops} unidades</span></div><div class="vehicle-roster"><span>${icon('tank')} ${esc(map.vehicleName('tank',c.id,c.armor))}</span><span>${icon('plane')} ${esc(map.vehicleName('jet',c.id,c.air))}</span><small>Modelos del juego · tu color y bandera</small></div>${Object.entries(defs).map(([key,[name,desc,ic]])=>actionButton(key,name+(key==='recruit'?'':pips(c[key])),key!=='recruit'&&c[key]>=4?'¡Al máximo!':desc,ic,key!=='recruit'&&c[key]>=4)).join('')}<button class="text-btn" data-ui="transfer" style="width:100%" ${!canAct()?'disabled':''}>${icon('trade')} MOVER REFUERZOS</button>${c.air===4?actionButton('bombers',c.bombers?'Bombarderos desbloqueados':'Desbloquear bombarderos',c.bombers?'Elige un país → Guerra → Industria':'Alcance: 2 pasos · solo industria','plane',!!c.bombers):'<p class="fineprint">Aviones nivel 4 desbloquean la mejora de bombarderos.</p>'}${convoySummary()}`;}
function foreign(c){const rel=Math.max(0,c.relation),until=treatyUntil(state,state.player,c.owner);return `<div class="relation-row"><span>Confianza</span><span>${rel} / 100</span></div><div class="relation"><i style="width:${rel}%"></i></div>${until>=state.turn?`<p class="fineprint">${icon('peace')} Tregua hasta el final de la ronda ${until}.</p>`:atWar(state,state.player,c.owner)?'<p class="fineprint">Estamos en guerra.</p>':''}<div class="stance-switch"><button data-stance="peace" class="${stance==='peace'?'active':''}">${icon('peace')} PAZ</button><button data-stance="war" class="${stance==='war'?'active':''}">${icon('tank')} GUERRA</button><button data-stance="neutral" class="${stance==='neutral'?'active':''}">${icon('trade')} COMERCIO</button></div>${stance==='peace'?`${actionButton('talk','Hablar','+35 confianza','peace')}${actionButton('peace','Hacer una tregua','4 rondas sin atacarse','shield')}${actionButton('join',state.campaignMode==='factions'?'Unir facciones':'Invitar a unirse',state.campaignMode==='factions'?(preparingFactions(state)?'Integra todos los países del bloque · 70 confianza':'Fusiones cerradas desde la ronda 5'):rel>=70?'Se une a tu nación sin combatir':'Primero llega a 70 de confianza','flag',rel<70||(state.campaignMode==='factions'&&!preparingFactions(state)))}`:stance==='neutral'?`${actionButton('trade','Comerciar','+20 ahora y +12 por ronda','trade',c.traded===state.turn)}<p class="country-tip">Ganas créditos y +10 confianza.</p><p class="fineprint">Dura 4 rondas. Una vez por país en cada ronda.</p>`:`${battle(c)}${bombardPanel(c)}`}`;}
function battle(c){const options=sourcesFor(state,c.id);if(!options.length)return '<div class="warning-inline">Para llegar, necesitas un vecino o aviones de nivel 2.</div>';if(!options.some(x=>x.id===source))source=options[0].id;const f=forecast(state,source,c.id),blocked=attackBlock(state,source,c.id),until=treatyUntil(state,state.player,c.owner);return `<label class="battle-label" for="attackSource">SALIR DESDE</label><div class="origin-with-flag">${flag(source)}<select id="attackSource">${options.map(o=>`<option value="${o.id}" ${source===o.id?'selected':''}>${BY_ID[o.id].name} · ${o.troops} unidades</option>`).join('')}</select></div><div class="force-compare"><span>${f.attack}<small>TU FUERZA</small></span><span style="font-size:14px;align-self:center;color:#6b898b">VS</span><span>${f.defense}<small>SU DEFENSA</small></span></div><div class="force-bar"><i style="width:${f.attack/(f.attack+f.defense)*100}%"></i></div><div class="forecast-chance">${blocked?'ATAQUE BLOQUEADO':`${f.chance>=65?'Buena oportunidad':f.chance>=40?'Está parejo':'Es arriesgado'} · ${f.chance}%`}</div><p class="fineprint">Van ${f.sent} unidades. El resto se queda cuidando tu país.</p>${[source,c.id].filter((id,i,a)=>a.indexOf(id)===i).map(id=>countryIncident(id,true)).join('')}${blocked?`<div class="warning-inline">${esc(blocked.reason)}<br>${esc(blocked.advice)}</div>`:''}${until>=state.turn?'<div class="warning-inline">Hay una tregua. Espera a que termine.</div>':''}<button class="primary danger" data-action="attack" ${!canAct()||state.ap<1||state.cash<25||state.countries[source].troops<12||until>=state.turn||blocked?'disabled':''}>${icon('tank')} ATACAR · 25 CR · 1 ACCIÓN</button>${!atWar(state,state.player,c.owner)?'<p class="fineprint">Atacar también declara la guerra.</p>':''}`;}
function industryStatus(id){const d=industryDamage(state,id);if(!d)return '';const c=state.countries[id];return `<div class="industry-status">${icon('factory')}<div><b>INDUSTRIA EN REPARACIÓN</b><span>Producción −75% · ${d.remaining} ${d.remaining===1?'turno':'turnos'} de su dueño.</span><small>Ingresos actuales: ${countryIncome(state,c)} cr. Se repara sola.</small></div></div>`;}
function routeChips(route){return `<div class="operation-route">${route.map((id,i)=>`${i?'<span>→</span>':''}<div>${flag(id)}<small>${BY_ID[id].name}</small></div>`).join('')}</div>`;}
function bombardPanel(c){const bases=bomberOrigins(state,c.id);if(!bases.length)return `<div class="bombard-panel"><div class="section-label">${icon('plane')} BOMBARDEO INDUSTRIAL</div><p class="fineprint">Necesitas una base con aviones nivel 4 y bombarderos desbloqueados, a un máximo de 2 pasos.</p></div>`;
 if(!bases.some(x=>x.id===bombSource))bombSource=bases[0].id;const route=airRoute(bombSource,c.id),reason=bombardBlock(state,bombSource,c.id),preview=countryIncome({...state,industryDamage:{...(state.industryDamage||{}),[c.id]:{remaining:2}}},c);
 return `<div class="bombard-panel"><div class="section-label">${icon('plane')} BOMBARDEO INDUSTRIAL</div><label class="battle-label" for="bombSource">BASE AÉREA</label><select id="bombSource">${bases.map(b=>`<option value="${b.id}" ${b.id===bombSource?'selected':''}>${BY_ID[b.id].name}</option>`).join('')}</select>${routeChips(route)}<p><b>${route.length-1} de 2 pasos</b> · fronteras o rutas marítimas</p><p class="fineprint">Fábricas −75% durante sus próximos 2 turnos.<br>Ingresos: <b>${countryIncome(state,c)} → ${preview} cr</b>. No conquista ni daña tropas.</p>${reason?`<div class="warning-inline">${esc(reason)}</div>`:''}<button class="secondary danger" data-ui="planBombard" ${reason||!canAct()||state.cash<BOMBARD.cost||state.ap<1?'disabled':''}>ELEGIR INDUSTRIA · ${BOMBARD.cost} CR · 1 ACCIÓN</button></div>`;
}
function operationConfirm(type,origin,target){
 operationChoice={type,origin,target};const bombing=type==='bombard',c=state.countries[target],f=bombing?null:forecast(state,origin,target);
 modal(`${close}<div class="operation-steps"><b>1 PREPARAR</b><span>2 VER</span><span>3 RESULTADO</span></div><div class="eyebrow">TÚ DECIDES CUÁNDO EMPEZAR</div><h2>${bombing?'OPERACIÓN<br>INDUSTRIAL.':'ANTES DE<br>LA BATALLA.'}</h2>${routeChips(bombing?airRoute(origin,target):[origin,target])}<p>${bombing?'Reducirás la producción de sus fábricas durante 2 turnos. El país seguirá siendo suyo.':`${f.sent} unidades salen de ${BY_ID[origin].name}. Posibilidad de victoria: ${f.chance}%.`}</p><div class="operation-summary">${bombing?'Solo industria · reparación automática':'Primero verás el combate. Después cambiará el mapa.'}</div><button class="primary danger" data-ui="confirmOperation">${bombing?'ENVIAR BOMBARDEROS':'IR A LA BATALLA'} · ${cost(state,type,target)} CR</button><button class="secondary" data-ui="peaceInstead" ${state.cash<35||state.ap<1?'disabled':''}>${icon('peace')} OFRECER TREGUA · 35 CR</button><button class="text-btn" data-ui="close">VOLVER SIN GASTAR</button><p class="fineprint">La operación o la tregua cuestan 1 acción. No hay cuenta regresiva.</p>`,false,'operation');
}
function battleBriefing(){const b=state.pendingBattle,defending=b.defender===state.player,bombing=b.type==='bombard';modal(`<div class="operation-steps"><b>1 PREPARAR</b><span>2 VER</span><span>3 RESULTADO</span></div><div class="eyebrow">${defending?'TU NACIÓN ESTÁ AMENAZADA':'OPERACIÓN RIVAL'}</div><h2>${bombing?'AVIONES EN<br>LA FRONTERA.':'UNIDADES EN<br>LA FRONTERA.'}</h2>${routeChips(bombing?b.route:[b.source,b.target])}<p>${factionLabel(b.attacker)} prepara ${bombing?'un bombardeo sobre la industria de':'un ataque a'} ${BY_ID[b.target].name}.</p><p class="operation-summary">${bombing?'Puede frenar sus fábricas. No cambia el territorio.':'Todavía no cambió el dueño del país. Mira lo que sucede.'}</p><button class="primary" data-ui="watchBattle">VER ${bombing?'OPERACIÓN':'BATALLA'} ${icon('arrow')}</button>${defending?`<button class="secondary" data-ui="battleTruce" ${state.cash<35?'disabled':''}>${icon('peace')} OFRECER TREGUA · 35 CR</button><p class="fineprint">Acuerdo de emergencia: evita el combate, sin gastar tus acciones del próximo turno.</p>`:''}<button class="text-btn" data-ui="resolveBattle">SALTAR ANIMACIÓN Y VER RESULTADO</button>`,false,'battleBriefing');}
function turnStep(){const id=currentFaction(state),r=state.aiReport;modal(`<div class="eyebrow">RONDA ${state.turn} · PASO A PASO</div><div class="notice-flags">${flag(id)}</div><h2>${r?'TURNO COMPLETADO.':`JUEGA ${factionLabel(id).toUpperCase()}.`}</h2>${r?`<div class="turn-review">${r.actions.map(a=>`<p>${icon(a.icon)} ${esc(a.text)}</p>`).join('')}</div>`:'<p>El país está listo para decidir. Tú marcas el ritmo.</p>'}<button class="primary" data-ui="continueRival">${r?'CONTINUAR AL SIGUIENTE PAÍS':'VER SUS DECISIONES'} ${icon('arrow')}</button><button class="secondary" data-ui="skipStep">IR A MI TURNO</button><button class="text-btn" data-ui="settings">CAMBIAR RITMO</button><p class="fineprint">Los resultados siempre esperan tu confirmación.</p>`,false,'turnStep');}
function drawModal(){modal(rouletteView(state,icon),false,'draw');}
function spin(){
 if(busy||state.phase!=='draw')return;const r=drawFirst(state);if(r.error)return;busy=true;save();$('#spinButton').disabled=true;$('#spinButton').textContent='SORTEANDO…';tone('turn');
 const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches,wait=spinRoulette($('#rouletteBelt'),r.first,reduced),epoch=gameEpoch;
 spinTimer=setTimeout(()=>{if(epoch!==gameEpoch)return;settleRoulette($('#rouletteBelt'),r.first);$('#drawCaption').textContent=`${BY_ID[r.first].name} juega primero.`;$('#spinButton').textContent='¡LISTO!';spinTimer=setTimeout(()=>{if(epoch!==gameEpoch)return;busy=false;dismiss();render();tone('win');},650);},wait);
}
function orderModal(){modal(`${close}<div class="eyebrow">RONDA ${state.turn}</div><h2>CADA BANDERA,<br>UNA VEZ.</h2><p>${state.turn===1?'La ruleta eligió al primero. Luego, menor poder primero.':'Menor poder primero. Los más fuertes esperan.'}</p><div class="order-grid">${state.turnOrder.map((o,i)=>`<div class="order-row ${i===state.turnIndex?'now':''}"><b>${i+1}</b>${flag(o.id)}<span>${factionLabel(o.id)}${o.id===state.player?' <em>TÚ</em>':''}</span><small>${o.power} poder</small></div>`).join('')}</div><p class="fineprint">El orden se fija al empezar cada ronda. Si una nación pierde todos sus países, su turno se salta. Los empates se sortean al crear la partida.</p><button class="primary" data-ui="close">ENTENDIDO</button>`,true);}
function noticeModal(){const n=pendingNotices(state)[0];if(!n)return;const end=n.kind==='endturn',combat=['battle','bombard'].includes(n.kind)||n.title.toLowerCase().includes('conquist')||n.title==='Industria dañada';modal(`<div class="notice-card ${n.kind}">${combat?'<div class="operation-steps"><span>1 PREPARAR</span><span>2 VER</span><b>3 RESULTADO</b></div>':''}<div class="eyebrow">${n.kind==='yourturn'?'TE TOCA JUGAR':`RONDA ${n.round} · NOTICIA`}</div><div class="notice-flags">${flag(n.actor)}${n.target&&n.target!==n.actor?`<span>${icon(n.icon)}</span>${flag(n.target)}`:`<span class="notice-symbol">${icon(n.icon)}</span>`}</div><h2>${esc(n.title)}</h2>${n.kind==='decision'?decisionDetails(state,n):`<p>${esc(n.text)}</p>`}${n.value?`<div class="notice-value">${esc(n.value)}</div>`:''}${n.kind==='yourturn'?'<div class="notice-stars">★ ★ ★</div>':''}<button class="primary" data-ui="ack">${end?'VER QUÉ PASA':n.kind==='yourturn'?'¡JUGAR!':combat?'ENTENDIDO · CONTINUAR':'ENTENDIDO'} ${icon('arrow')}</button>${end?'<button class="secondary" data-ui="skipFromNotice" style="margin-top:10px">SALTAR HASTA MI TURNO</button>':''}${n.kind==='calendar'?'<p class="fineprint">Despacho mundial · titular ficticio</p>':''}${state.fastForward?'<button class="text-btn" data-ui="pauseFastForward">PAUSAR SALTO AUTOMÁTICO</button><p class="fineprint">Continuará automáticamente tras mostrar este aviso.</p>':''}<small class="notice-count">${state.inbox.length>1?`${state.inbox.length-1} noticias más`:'Queda guardado en Noticias'}</small></div>`,false,'notice');if(state.fastForward){const epoch=gameEpoch;noticeTimer=setTimeout(()=>{if(epoch===gameEpoch&&modalKind==='notice'&&pendingNotices(state)[0]?.id===n.id)acknowledgeOne();},3200);}}
function reportModal(){const notices=pendingNotices(state),changes=notices.filter(n=>!['yourturn','endturn'].includes(n.kind));modal(`<div class="eyebrow">TE SALTASTE LA ESPERA</div><h2>${state.status==='lost'?'TU CAMPAÑA TERMINÓ.':'¡YA ES TU TURNO!'}</h2><p>${state.rivalTurns.length} turnos rivales · ${changes.length} noticias importantes.</p><div class="report-list">${changes.length?changes.map(n=>`<article class="report-item ${n.kind}">${flag(n.actor)}<div><b>${esc(n.title)}</b><p>${esc(n.text)}</p>${n.details?.incident?`<small>${incidentTime(state,n.details.incident)}</small>`:''}${n.value?`<small>${esc(n.value)}</small>`:''}</div>${icon(n.icon)}</article>`).join(''):'<div class="report-item">No hubo cambios importantes.</div>'}</div>${state.rivalTurns.length?`<details class="rival-detail"><summary>Ver sus mejoras y movimientos (${state.rivalTurns.length})</summary>${state.rivalTurns.map(r=>`<div class="rival-detail-row">${flag(r.faction)}<div><b>${factionLabel(r.faction)}</b><p>${r.actions.map(a=>esc(a.text)).join(' · ')}</p></div></div>`).join('')}</details>`:''}${notices.find(n=>n.kind==='yourturn')?`<div class="report-income">${esc(notices.find(n=>n.kind==='yourturn').value)} <span>★ ★ ★</span></div>`:''}<p class="fineprint">Los ataques a tus países se muestran antes de continuar. El resto queda en este recuento.</p><button class="primary" data-ui="ackReport">${state.status==='playing'?'¡JUGAR MI TURNO!':'VER RESULTADO'} ${icon('arrow')}</button>`,true,'report');}
function nextRival(){if(mode!=='play'||state.phase!=='ai'||busy||modalKind||interfaceState.hidden)return;stopAI();if(state.aiReport)finishAITurn(state);else playAITurn(state);save();render();}
function skipOne(){if(state.phase!=='ai'||modalKind||busy)return;stopAI();if(!state.aiReport)playAITurn(state);if(state.pendingBattle?.defender!==state.player&&state.status==='playing')finishAITurn(state);save();render();}
function advanceSkip(){
 const deferred=new Set(state.skipDeferred||[]);for(const id of state.inbox)deferred.add(id);state.inbox=[];
 const result=skipToPlayer(state,{stopAtPlayerAttack:true});
 if(result.interrupted){const b=state.pendingBattle;for(const id of state.inbox){const n=state.notifications.find(x=>x.id===id);if(!(n?.kind==='war'&&n.actor===b.attacker&&n.target===state.player))deferred.add(id);}state.inbox=state.inbox.filter(id=>!deferred.has(id));state.skipDeferred=[...deferred];skipReport=false;selected=b.target;turnViewKey=turnKey();}
 else{state.inbox=[...new Set([...deferred,...state.inbox])].filter(id=>state.notifications.some(n=>n.id===id&&!n.read));state.skipDeferred=[];state.fastForward=false;skipReport=true;turnViewKey='';}
 save();dismiss();render();
}
function skipAll(){if(!state||state.phase!=='ai'||busy)return;stopAI();state.fastForward=true;dismiss();advanceSkip();}
function pauseFastForward(){stopAI();clearTimeout(noticeTimer);state.fastForward=false;state.inbox=[...new Set([...(state.skipDeferred||[]),...state.inbox])];state.skipDeferred=[];save();dismiss();render();}

function acknowledgeOne(){acknowledge(state);save();dismiss();render();}
function doAction(type,origin=source,confirmed=false){if(!canAct())return;if(['attack','bombard'].includes(type)&&!confirmed){operationConfirm(type,origin,selected);return;}const r=action(state,type,selected,origin);if(r.error){toast(r.error);tone('bad');return;}if(type==='transfer')selected=origin;save();if(!['attack','bombard'].includes(type))tone(type==='join'?'win':'click');dismiss();render();if(type==='transfer')map?.focusCountry(origin);}
function finishMyTurn(){if(!isPlayerTurn(state)||busy||modalKind)return;const r=endTurn(state);if(r.error){toast(r.error);return;}tip=false;save();render();tone('turn');}
function actionsHelp(){modal(`${close}<div class="eyebrow">LAS 3 FICHAS SON TUYAS</div><h2>3 ACCIONES.<br>COMO TÚ QUIERAS.</h2><div class="big-three">★ ★ ★</div><p>Cada mejora, trato o ataque gasta una ficha.</p><div class="peaceful-example"><span>${icon('factory')}Industria</span><b>+</b><span>${icon('troops')}Reclutar</span><b>+</b><span>${icon('shield')}Defender</span></div><p class="example-caption">¡Listo! Jugaste tus 3 acciones sin atacar.</p><button class="primary" data-ui="close">¡ENTENDIDO!</button>`);}
function showHelp(){if(busy)return;modal(`${close}<div class="eyebrow">APRENDE EN UN MOMENTO</div><h2>ASÍ SE JUEGA.</h2><div class="short-help"><div>${icon('flag')}<span><b>1. Elige una bandera.</b>La ruleta decide quién empieza.</span></div><div>${icon('star')}<span><b>2. Usa tus 3 acciones.</b>Mejora, negocia o ataca. Tú eliges.</span></div><div>${icon('globe')}<span><b>3. Mira a los demás.</b>Puedes saltar; verás los ataques a tus países antes de seguir.</span></div><div>${icon('check')}<span><b>4. Reúne los 20 países.</b>Con acuerdos o conquistas.</span></div></div><p class="fineprint">Cada ronda avanza una semana. Consulta el calendario para la paz mundial y sus bonificaciones. Al iniciar una campaña puedes elegir el modo Facciones y diseñar tu bandera.</p><p class="example-caption">Puedes usar las 3 acciones en tu país.<br><b>No tienes que atacar.</b></p><button class="primary" data-ui="close">¡VAMOS!</button><button class="text-btn" data-ui="controls">Ver controles y más detalles</button>`);}
function controlsModal(){modal(`${close}<div class="eyebrow">CUANDO LO NECESITES</div><h2>UN POCO MÁS.</h2><div class="short-help"><p>Arrastra para mover el mapa. Usa la rueda o +/− para acercar. En móvil: un dedo mueve y dos dedos hacen zoom. Toca la ficha inferior para abrir acciones. Solo mapa oculta la interfaz; Ver interfaz la recupera. Los turnos y avisos esperan mientras miras el mapa libremente. Pulsa Girar para cambiar el gesto. El clic derecho también gira.</p><p>Cada bandera tiene un turno por ronda. Ganas créditos cuando vuelve tu turno. Las acciones que no uses no se acumulan.</p><p>Para atacar, necesitas una frontera, una ruta marítima o aviones nivel 2. La probabilidad aparece antes del ataque.</p><p>Bombarderos: aviones nivel 4, mejora de 140 créditos. Cada salida cuesta 55 créditos y 1 acción. Alcance de 2 pasos del mapa; reduce la producción industrial 75% durante los próximos 2 turnos del dueño. Conserva los 12 créditos básicos. No conquista. Viento, combustible y treguas impiden despegar.</p><p>En Paso a paso cada país espera tu OK. Antes de una batalla puedes elegir una tregua. Los resultados siempre se leen después del combate.</p><p>Los rivales no te atacan en las primeras 2 rondas. Si pierdes todos tus países, termina tu campaña.</p></div><button class="primary" data-ui="close">ENTENDIDO</button>`);}
function showSettings(){if(busy)return;modal(`${close}<div class="eyebrow">UN RESPIRO</div><h2>PAUSA.</h2><div class="setting-row"><span>Sonidos</span><button class="switch" data-ui="toggleSound">${sound?'ACTIVADOS':'DESACTIVADOS'}</button></div><div class="setting-row"><label for="quality">Gráficos</label><select id="quality"><option value="high" ${!low?'selected':''}>Alta calidad</option><option value="low" ${low?'selected':''}>Más ligero</option></select></div><div class="setting-row"><label for="pace">Ritmo entre decisiones</label><select id="pace"><option value="step" ${stepByStep?'selected':''}>Paso a paso · con OK</option><option value="auto" ${!stepByStep?'selected':''}>Automático · pausado</option></select></div><div class="setting-row"><span>Viajar al país de cada turno</span><button class="switch" data-ui="toggleCamera">${followCamera?'ACTIVADO':'DESACTIVADO'}</button></div><div class="modal-buttons"><button class="secondary" data-ui="help">CÓMO JUGAR</button><button class="secondary" data-ui="credits">CRÉDITOS</button></div>${mode!=='menu'?`<button class="secondary" data-ui="menu" style="margin-top:10px">${mode==='play'?'GUARDAR Y SALIR AL INICIO':'VOLVER AL INICIO'}</button>`:''}<button class="primary" data-ui="close">SEGUIR</button>`);}
function showCredits(){modal(`${close}<div class="eyebrow">UNA IDEA EN FAMILIA</div><h2>NUESTRO EQUIPO.</h2><p class="credits-game-title">DOMINIO <span>Last Frontier: Latinoamérica</span></p><p class="credits-title">Ian · Diego · María Paz</p><p>Idea original de Ian. Un juego creado en familia con diseño y desarrollo asistidos por ChatGPT.</p><div class="divider"></div><p class="fineprint">Mapas: Natural Earth (dominio público). Motor: Three.js (MIT). Banderas: flag-icons (MIT). Tipografía: Barlow Condensed, Jeremy Tribby (SIL OFL). Tanques: Low_Poly Tanks, Ishmael (CC BY). Aviones: low poly jets, Ishmael (CC0). Modelos adaptados, normalizados y animados para Dominio. Edificios: geometría del juego. Los modelos son fichas de juego, no inventarios militares reales.</p><p class="fineprint">Presentación de turnos y avisos inspirada en la campaña de Rome: Total War. La ruleta y el orden por poder son reglas propias de Dominio. Noticias ficticias inspiradas en los titulares de Plague Inc.</p><p class="fineprint"><a href="https://blendswap.com/blend/29639" target="_blank" rel="noopener">Tanques · Ishmael ↗</a> · <a href="https://blendswap.com/blend/31097" target="_blank" rel="noopener">Aviones · Ishmael ↗</a> · <a href="./assets/vehicles/ATTRIBUTION.txt" target="_blank" rel="noopener">Atribución y licencias ↗</a></p><button class="secondary" data-ui="sources">DATOS Y FUENTES</button><button class="primary" data-ui="close">VOLVER</button>`);}
function showSources(){modal(`${close}<div class="eyebrow">PARA SABER MÁS</div><h2>DATOS Y REFERENCIAS.</h2><p>La población es una aproximación de 2024. El personal militar corresponde al Atlas RESDAL 2024; sus fuentes tienen distintas fechas y definiciones. No es una medida comparable de militares activos actuales.</p><p>Costa Rica y Panamá no tienen ejército permanente. Cuba no tiene un dato comparable en esa tabla. Las tropas, créditos y mejoras del juego son ficticios.</p><div class="source-list">${SOURCES.map(s=>`<a href="${s.url}" target="_blank" rel="noopener">${s.title} ↗</a>`).join('')}<a href="https://cdn.akamai.steamstatic.com/steam/apps/4760/manuals/manual_en.pdf" target="_blank" rel="noopener">Rome: Total War · Manual original, mensajes y turnos ↗</a><a href="https://www.feralinteractive.com/en/manuals/rometwremastered/2.0.5/windows_stm/" target="_blank" rel="noopener">ROME REMASTERED · Animaciones y noticias ↗</a></div><p class="fineprint">20 países soberanos latinoamericanos de lenguas romances. Los vecinos en gris son contexto. Rutas marítimas simplificadas para el juego; cartografía generalizada de Natural Earth.</p><button class="primary" data-ui="close">VOLVER</button>`,true);}
function showNations(){modal(`${close}<div class="eyebrow">ELIGE UNA BANDERA</div><h2>¿A DÓNDE VAMOS?</h2><div class="nation-grid">${COUNTRIES.map(c=>{const sc=state?.countries[c.id],own=sc?.owner===state?.player;return `<button class="nation-option" data-pick="${c.id}">${flag(c.id)}<span>${c.name}<small>${state?`${own?'Tu país':factionLabel(sc.owner)} · ${power(sc)} poder`:`${c.population.toLocaleString('es-CL',{maximumFractionDigits:1})} M habitantes`}</small></span></button>`;}).join('')}</div>`,true);}
function journal(){modal(`${close}<button class="secondary" data-ui="incidents" style="margin-bottom:20px">${icon('globe')} SUCESOS ACTIVOS · ${activeIncidents(state).length}</button><div class="eyebrow">NADA SE PIERDE</div><h2>NOTICIAS.</h2>${state.log.map(l=>`<div class="log-entry ${esc(l.kind)}">${l.actor?flag(l.actor):''}<b>R${l.turn}</b>${esc(l.text)}</div>`).join('')}`,true);}
function transferModal(){if(!canAct())return;const origins=transferOrigins(state,selected);modal(`${close}<div class="eyebrow">MOVER REFUERZOS</div><h2>RUMBO A<br>${BY_ID[selected].name.toUpperCase()}.</h2>${origins.length?`<p>Envía la mitad de las unidades. Avanzan <b>un país por turno tuyo</b>.</p><label class="battle-label" for="transferSource">SALIR DESDE</label><select id="transferSource">${origins.map(c=>`<option value="${c.id}">${BY_ID[c.id].name} · ${Math.floor(c.troops*.5)} unidades</option>`).join('')}</select><div id="routePreview"></div><p class="fineprint">Salen en tu próximo turno. Solo pasan por países tuyos. Cuesta 1 acción; después avanzan solos.</p><button class="primary" data-ui="doTransfer" ${state.ap<1?'disabled':''}>PREPARAR CONVOY · 1 ACCIÓN</button>`:'<p>Necesitas otro país tuyo con 16 unidades y un camino de países tuyos hasta aquí.</p><button class="primary" data-ui="close">ENTENDIDO</button>'}`);updateRoutePreview();}
function updateRoutePreview(){const el=$('#routePreview'),origin=$('#transferSource')?.value;if(!el||!origin)return;const route=friendlyRoute(state,origin,selected),blocked=routeBlock(state,route);el.innerHTML=`<div class="route-steps">${route.map((id,i)=>`${i?'<span class="route-arrow">→</span>':''}<span>${flag(id)}<small>${i===0?'SALIDA':`TURNO +${i}`}</small><b>${BY_ID[id].name}</b></span>`).join('')}</div><div class="route-time">${blocked?'RUTA EN PAUSA':`Llega en ${route.length-1} ${route.length===2?'turno tuyo':'turnos tuyos'}`} · ${Math.floor(state.countries[origin].troops*.5)} unidades</div>${blocked?`<div class="warning-inline">${esc(blocked.reason)}<br>Elige otro origen o espera.</div>`:'<p class="fineprint">El tiempo puede aumentar si aparece un suceso en el camino.</p>'}`;const send=$('[data-ui="doTransfer"]');if(send)send.disabled=!!blocked||state.ap<1;}

function convoySummary(){return state.transfers.length?`<button class="convoy-summary" data-ui="convoys">${icon('troops')} ${state.transfers.length} ${state.transfers.length===1?'convoy en camino':'convoyes en camino'} ${icon('arrow')}</button>`:'';}
function convoys(){modal(`${close}<div class="eyebrow">UN PASO POR TURNO</div><h2>TUS REFUERZOS.</h2>${state.transfers.length?state.transfers.map(t=>{const held=movementBlock(state,t.route[t.step],t.route[t.step+1]);return `<article class="convoy-card"><div>${flag(t.owner)}<b>${t.troops} unidades → ${BY_ID[t.route.at(-1)].name}</b></div><p>Ahora: ${BY_ID[t.route[t.step]].name} · Faltan ${t.route.length-1-t.step} pasos.</p>${held?`<div class="warning-inline">EN ESPERA · ${esc(held.reason)}</div>`:''}<div class="route-steps">${t.route.map((id,i)=>`${i?'<span class="route-arrow">→</span>':''}<span class="${i===t.step?'current':''}">${flag(id)}<small>${BY_ID[id].name}</small></span>`).join('')}</div><button class="secondary" data-cancel-convoy="${t.id}" ${!canAct()?'disabled':''}>CANCELAR · DEJAR UNIDADES AQUÍ</button></article>`;}).join(''):'<p>No hay refuerzos viajando.</p>'}<p class="fineprint">Los sucesos pueden pausar el viaje. Al terminar, avanza solo. Cancelar deja las unidades en su país actual, sin gastar acciones.</p><button class="primary" data-ui="close">ENTENDIDO</button>`,true);}

function newsTicker(){const wars=liveWars(state),events=activeIncidents(state),global=worldEvent(state),news=[...(global?[WORLD_NEWS[global.kind].title+'. '+worldHeadline(global)+' '+WORLD_NEWS[global.kind].effect]:[]),...Object.entries(state.industryDamage||{}).map(([id,d])=>`${BY_ID[id].name}: industria en reparación, ${d.remaining} turnos de su dueño. Producción −75%.`),...events.map(e=>`${BY_ID[e.target].name}: ${INCIDENTS[e.kind].title}. ${INCIDENTS[e.kind].effect}`),...state.log.slice(0,5).map(l=>l.text)],summary=news.join('   •   ');return `<aside class="world-ticker" aria-label="Noticias de la partida"><button data-ui="calendar" class="calendar-ticker">${dateLabel(state)}</button><button data-ui="incidents" class="event-ticker-button">${icon('globe')} SUCESOS <b>${events.length}</b></button><button data-ui="worldStatus" class="conflict-status ${wars.length?'has-war':''}"><i></i>${combatPause(state)?'CESE GLOBAL':wars.length?`${wars.length} CONFLICTOS`:'SIN GUERRAS'}</button><button class="ticker-news" data-ui="journal" aria-label="Abrir todas las noticias"><span>${esc(summary||'El continente espera tu primera decisión.')}</span></button><button class="ticker-convoys" data-ui="convoys" title="Ver refuerzos">${icon('troops')} ${state.transfers.length}</button></aside>`;}

function worldStatus(){const alive=activeFactions(state),wars=liveWars(state),treaties=Object.entries(state.treaties).filter(([key,until])=>until>=state.turn&&key.split(':').every(id=>alive.includes(id))),neutral=alive.filter(id=>!wars.some(k=>k.split(':').includes(id)));const row=(key,label)=>{const [a,b]=key.split(':');return `<div class="diplomacy-row">${flag(a)}<span>${factionLabel(a)}<small>${label}</small>${factionLabel(b)}</span>${flag(b)}</div>`;};modal(`${close}<div class="eyebrow">ASÍ ESTÁ EL CONTINENTE</div><h2>GUERRA Y PAZ.</h2>${combatPause(state)?`<div class="warning-inline">${combatPause(state)}</div>`:''}${state.campaignMode==='factions'?`<button class="secondary" data-ui="factions">VER LAS FACCIONES</button>`:''}<div class="section-label">EN CONFLICTO · ${wars.length}</div>${wars.map(k=>row(k,'EN GUERRA')).join('')||'<p>No hay guerras activas.</p>'}<div class="section-label">TREGUAS · ${treaties.length}</div>${treaties.map(([k,u])=>row(k,`PAZ HASTA RONDA ${u}`)).join('')||'<p>No hay treguas firmadas.</p>'}<div class="section-label">SIN GUERRAS DECLARADAS</div><div class="peace-flags">${neutral.map(id=>`<span>${flag(id)}${factionLabel(id)}</span>`).join('')||'<p>Todas las naciones tienen un conflicto.</p>'}</div><button class="primary" data-ui="close">VOLVER AL MAPA</button>`,true);}
async function playScene(){
 if(busy)return;busy=true;interfaceState.closePanel();applyInterfaceState();stopAI();const epoch=gameEpoch,battle=state.pendingBattle,occupation=!battle?state.pendingOccupation:null,moves=state.movements.slice(),root=$('#sceneOverlay'),operation=battle||occupation;
 document.body.classList.add('in-scene');root.innerHTML=`<div class="scene-heading"><small>${battle?battle.type==='bombard'?'OPERACIÓN INDUSTRIAL':'ENFRENTAMIENTO':occupation?'OCUPACIÓN DEL TERRITORIO':'REFUERZOS EN MARCHA'}</small><div>${flag(operation?operation.attacker||operation.owner:state.player)}<h2>${operation?`${BY_ID[operation.source].name} <em>→</em> ${BY_ID[operation.target].name}`:'UN PAÍS POR TURNO'}</h2>${battle?flag(battle.defender):''}</div><p id="sceneStage">Preparando unidades…</p>${state.fastForward?'<small>Se mostrará el cambio y continuará hasta tu turno.</small>':''}</div><button class="secondary scene-skip" data-ui="skipAnimation">SALTAR ANIMACIÓN ${icon('arrow')}</button>`;
 const stage=text=>{if($('#sceneStage'))$('#sceneStage').textContent=text;};
 try{if(battle)await (battle.type==='bombard'?map.animateBombardment(battle,stage):map.animateBattle(battle,stage));else if(occupation)await map.animateOccupation(occupation,stage);else await map.animateMovements(moves,stage);}
 catch(error){console.error(error);map.skipAnimation();toast('La animación no pudo completarse. Verás el resultado a continuación.');}
 finally{if(epoch===gameEpoch){if(battle)finishBattle(state);else if(occupation)finishOccupation(state);else finishMovements(state);busy=false;document.body.classList.remove('in-scene');root.innerHTML='';save();render();if(battle)tone(battle.won?'win':'bad');}}
}
function calendarModal(){modal(`${close}${calendarView(state,icon)}<button class="primary" data-ui="close">VOLVER AL MAPA</button>`,false,'calendar');}
function factionsModal(){modal(`${close}<div class="eyebrow">${preparingFactions(state)?'PREPARAR Y UNIR':'CONFRONTACIÓN FINAL'}</div><h2>LAS FACCIONES.</h2><p>${preparingFactions(state)?'Habla con un país de otro bloque hasta llegar a 70 de confianza. Unirlo integra todos sus países por 80 créditos y 1 acción. Las fusiones cierran en la ronda 5.':'Las fusiones terminaron. Reúne los 20 países mediante conquistas; puedes seguir negociando treguas.'}</p><div class="faction-list">${activeFactions(state).map(id=>`<article>${flag(id)}<div><b>${factionLabel(id)}</b><p>${Object.values(state.countries).filter(c=>c.owner===id).map(c=>BY_ID[c.id].name).join(' · ')}</p></div></article>`).join('')}</div><button class="primary" data-ui="close">VOLVER</button>`,true);}


let incidentNoticeIds=[],incidentFilter='active';
function countryIncident(id,compact=false){const e=incidentAt(state,id);if(!e)return '';const d=INCIDENTS[e.kind];return `<button class="country-incident ${d.tone} ${compact?'compact':''}" data-ui="incidents"><span>${eventSymbol(e.kind)}</span><span><b>${d.title}${compact?` · ${BY_ID[id].name}`:''}</b><small>${d.effect}</small><em>Hasta R${e.until} · Ver sucesos</em></span></button>`;}
function incidentNotice(){const notices=pendingNotices(state),group=[];for(const n of notices){if(!['incidentStart','incidentEnd'].includes(n.kind))break;group.push(n);}incidentNoticeIds=group.map(n=>n.id);const affected=group.some(n=>state.countries[n.target].owner===state.player);modal(`<div class="incident-window"><div class="eyebrow">RONDA ${state.turn} · EL CONTINENTE CAMBIA</div><h2>${affected?'ATENCIÓN A<br>TUS PAÍSES.':'NOTICIAS DEL<br>CONTINENTE.'}</h2><p class="incident-window-intro">${group.length} ${group.length===1?'suceso cambia las decisiones':'sucesos cambian las decisiones'}.</p><div class="incident-card-list">${group.map(n=>incidentCard(state,n.details.incident,{stage:n.details.stage,compact:group.length>3})).join('')}</div><p class="incident-footnote">Sucesos del juego. Afectan al jugador y a los rivales.</p><button class="primary" data-ui="ackIncidents">ENTENDIDO · SEGUIR ${icon('arrow')}</button></div>`,true,'incident');}
function ackIncidents(){acknowledge(state,incidentNoticeIds);incidentNoticeIds=[];save();dismiss();render();}
function incidentCenter(){const all=activeIncidents(state),mine=all.filter(e=>state.countries[e.target].owner===state.player),history=state.incidentHistory.filter(e=>e.until<state.turn).slice(0,30),events=incidentFilter==='mine'?mine:incidentFilter==='history'?history:all;modal(`${close}<div class="eyebrow">QUÉ PASA Y QUÉ CAMBIA</div><h2>SUCESOS DEL<br>CONTINENTE.</h2><div class="incident-filters"><button data-incident-filter="active" class="${incidentFilter==='active'?'active':''}">ACTIVOS · ${all.length}</button><button data-incident-filter="mine" class="${incidentFilter==='mine'?'active':''}">MIS PAÍSES · ${mine.length}</button><button data-incident-filter="history" class="${incidentFilter==='history'?'active':''}">TERMINADOS</button></div><div class="incident-card-list">${events.length?events.map(e=>`${incidentCard(state,e,{stage:incidentFilter==='history'?'end':'active'})}<button class="incident-map-button" data-incident-map="${e.target}">${icon('map')} VER ${BY_ID[e.target].name.toUpperCase()} EN EL MAPA</button>`).join(''):`<div class="incident-empty">${icon('sun')}<p>${incidentFilter==='history'?'Todavía no han terminado sucesos.':incidentFilter==='mine'?'Tus países están en calma.':'El continente está en calma.'}</p></div>`}</div><details class="incident-rules"><summary>¿Cómo funcionan?</summary><p>Hasta 3 sucesos nuevos por ronda, en países al azar. Todos tienen oportunidad de recibirlos. Duran 1 o 2 rondas; no se acumulan y hay un descanso antes de repetir en un país.</p><p>Un bloqueo no gasta acciones ni créditos. Los convoyes esperan y continúan cuando pueden. Siempre puedes negociar.</p></details><button class="primary" data-ui="close">VOLVER AL JUEGO</button>`,true);}
function eventModal(){const e=state.event;modal(`<div class="eyebrow">¡UNA SORPRESA!</div><h2>${esc(e.title)}</h2><p>${esc(e.text)}</p><div class="event-options">${e.options.map((o,i)=>`<button data-event="${i}">${esc(o.label)} ${icon('arrow')}</button>`).join('')}</div><p class="fineprint">No gasta acciones.</p>`,false,'event');}
function resultModal(){const won=state.status==='won';modal(`<div class="result-modal"><div class="result-emblem">${icon(won?'star':'flag')}</div><div class="eyebrow">FIN DE CAMPAÑA</div><h2>${won?'¡LO LOGRASTE!':'¡BUEN INTENTO!'}</h2><p>${won?'Las 20 banderas están en tu nación.':'Perdiste tu último país. Puedes probar otra estrategia.'}</p><div class="result-stats"><div><strong>${state.turn}</strong><small>RONDAS</small></div><div><strong>${state.stats.battles}</strong><small>CONQUISTAS</small></div><div><strong>${state.stats.agreements}</strong><small>ACUERDOS</small></div></div><button class="primary" data-ui="menu">VOLVER AL MENÚ</button><button class="secondary" data-ui="new" style="margin-top:10px">NUEVA CAMPAÑA</button><button class="text-btn" data-ui="viewEnd">VER EL MAPA FINAL</button></div>`,false,'result');tone(won?'win':'bad');}
function chooseNew(){interfaceState.reset();turnViewKey='';map?.navigation.cancel();stopAI();clearTimeout(spinTimer);gameEpoch++;busy=false;state=null;mode='choose';selected='CHL';tab='actions';resultShown=false;dismiss();map.reset();render();}
function newCampaign(){if(saved?.status==='playing'){modal(`${close}<div class="eyebrow">UN NUEVO COMIENZO</div><h2>¿OTRA CAMPAÑA?</h2><p>La nueva partida reemplazará la guardada.</p><button class="primary" data-ui="confirmNew">ELEGIR OTRO PAÍS</button><button class="secondary" data-ui="continue" style="margin-top:10px">SEGUIR MI PARTIDA</button>`);}else chooseNew();}
function territoriesModal(){modal(`${close}${territoryLegendView(state,flag)}<button class="primary" data-ui="close">VOLVER AL MAPA</button>`,true,'territories');}
const handlers={territories:territoriesModal,calendar:calendarModal,factions:factionsModal,pauseFastForward,
 planBombard:()=>doAction('bombard',bombSource),
 confirmOperation:()=>{const o=operationChoice;if(!o)return;selected=o.target;dismiss();doAction(o.type,o.origin,true);},
 peaceInstead:()=>{const o=operationChoice;if(!o)return;selected=o.target;dismiss();doAction('peace');},
 watchBattle:()=>{beginBattle(state);save();dismiss();render();},
 resolveBattle:()=>{finishBattle(state);save();dismiss();render();},
 battleTruce:()=>{const r=offerBattleTruce(state);if(r.error){toast(r.error);return;}save();dismiss();render();},
 continueRival:()=>{dismiss();nextRival();},skipStep:()=>{dismiss();skipAll();},
 toggleInterface,openPanel:openCountryPanel,closePanel:closeCountryPanel,mobileNews,mapCamera:cameraModal,skipTravel:()=>map.skipTravel(),toggleCamera:()=>{followCamera=!followCamera;saveSettings();showSettings();},new:newCampaign,confirmNew:chooseNew,start:()=>{interfaceState.reset();turnViewKey='';gameEpoch++;state=createGame(selected,difficulty,Date.now()>>>0,campaignOptions);mode='play';tip=true;resultShown=false;autoWatch=true;skipReport=false;save();dismiss();render();},spin,begin:()=>{beginCampaign(state);save();dismiss();render();},continue:()=>{interfaceState.reset();turnViewKey='';saved=readSave()||saved;if(!saved){toast('No hay una partida guardada.');return;}gameEpoch++;state=structuredClone(saved);selected=owned(state)[0]?.id||state.player;mode='play';resultShown=false;skipReport=!state.fastForward&&!state.pendingOccupation&&!state.pendingBattle&&state.inbox.length>0&&state.phase==='player'&&state.rivalTurns.length>0;dismiss();save();render();},menu:()=>{stopAI();clearTimeout(spinTimer);gameEpoch++;busy=false;if(state)save();dismiss();mode='menu';saved=readSave()||saved;render();},close:closeModal,help:showHelp,controls:controlsModal,actionsHelp,settings:showSettings,credits:showCredits,sources:showSources,nations:showNations,journal,convoys,worldStatus,incidents:()=>{incidentFilter='active';incidentCenter();},ackIncidents,skipAnimation:()=>map.skipAnimation(),order:orderModal,transfer:transferModal,doTransfer:()=>{const origin=$('#transferSource')?.value;dismiss();doAction('transfer',origin);},endturn:finishMyTurn,ack:acknowledgeOne,ackReport:()=>{acknowledge(state,state.inbox.slice());skipReport=false;save();dismiss();render();},skipFromNotice:()=>{acknowledge(state);dismiss();skipAll();},skipAll,skipOne,nextRival,pauseWatch:()=>{autoWatch=!autoWatch;render();},home:()=>{const id=owned(state).find(c=>c.id===state.player)?.id||owned(state)[0]?.id||selected;selectCountry(id);},hidetip:()=>{tip=false;render();},toggleSound:()=>{sound=!sound;saveSettings();tone();render();showSettings();},viewEnd:()=>{dismiss();render();}};
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;if(busy&&!['skipAnimation','skipTravel','toggleInterface'].includes(b.dataset.ui)&&!(turnTravelling&&b.dataset.map))return;if(b.dataset.cancelConvoy){const r=cancelTransfer(state,b.dataset.cancelConvoy);if(r.error){toast(r.error);return;}save();dismiss();render();return;}if(b.dataset.controlOwner){const id=turnFocusId(state,b.dataset.controlOwner);if(id){dismiss();selectCountry(id);}return;}if(b.dataset.incidentFilter){incidentFilter=b.dataset.incidentFilter;incidentCenter();return;}if(b.dataset.incidentMap){dismiss();selectCountry(b.dataset.incidentMap);return;}if(b.dataset.ui){handlers[b.dataset.ui]?.();return;}if(b.dataset.country){selectCountry(b.dataset.country);return;}if(b.dataset.pick){dismiss();selectCountry(b.dataset.pick,{openPanel:true});return;}if(b.dataset.mode){campaignOptions.mode=b.dataset.mode;render();return;}if(b.dataset.difficulty){difficulty=b.dataset.difficulty;render();return;}if(b.dataset.tab){tab=b.dataset.tab;render();return;}if(b.dataset.stance){stance=b.dataset.stance;render();return;}if(b.dataset.action){doAction(b.dataset.action);return;}if(b.dataset.event!==undefined){resolveEvent(state,Number(b.dataset.event));dismiss();save();render();tone('win');return;}if(b.dataset.map){handleMapControl(b.dataset.map);}});
document.addEventListener('change',e=>{if(e.target.dataset.faction){campaignOptions[e.target.dataset.faction]=e.target.value;if(e.target.dataset.faction==='name'){const label=$('.faction-preview strong');if(label)label.textContent=e.target.value.trim()||'Unión del Horizonte';return;}render();return;}if(e.target.id==='transferSource')updateRoutePreview();if(e.target.id==='pace'){stepByStep=e.target.value!=='auto';saveSettings();}if(e.target.id==='bombSource'){bombSource=e.target.value;render();}if(e.target.id==='attackSource'){source=e.target.value;render();}if(e.target.id==='quality'){low=e.target.value==='low';saveSettings();map.setQuality(low);}});
document.addEventListener('input',e=>{if(e.target.id==='factionName')campaignOptions.name=e.target.value;});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&interfaceState.hidden){e.preventDefault();toggleInterface();return;}if(busy){if(e.key==='Escape'){if(turnTravelling)map.skipTravel();else map.skipAnimation();}return;}if(e.key==='Tab'&&modalKind){const focusable=[...$('#modalRoot').querySelectorAll('button:not(:disabled),a,select')],first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}return;}if(e.key==='Escape'){if(modalKind)closeModal();else if(isCompact()&&interfaceState.panelOpen)closeCountryPanel();else showSettings();return;}if(interfaceState.hidden||modalKind||['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName))return;if(e.key==='+'||e.key==='=')map?.zoom(.85);if(e.key==='-')map?.zoom(1.15);if(e.key.toLowerCase()==='h'&&mode==='play')handlers.home();});
compactMedia.addEventListener('change',()=>{interfaceState.closePanel();if(map)render();});
$('#helpBtn').onclick=showHelp;$('#settingsBtn').onclick=showSettings;$('#brand').onclick=()=>mode==='play'?showSettings():handlers.menu();$('#soundBtn').onclick=()=>{sound=!sound;saveSettings();tone();render();};
try{map=new WorldMap($('#world'),selectCountry);await map.load();map.onViewChange=updateMapControls;map.onInteraction=active=>{if(active)stopAI();else present();};map.onFire=()=>tone('bad');map.setQuality(low);render();$('#loader').classList.add('ready');setTimeout(()=>$('#loader').remove(),650);}catch(error){console.error(error);if(map)map.running=false;const notice=startupNotice(error);$('#loader').innerHTML=`<div class="loader-emblem">D</div><p>${esc(notice.title)}</p><div style="max-width:340px;padding:20px;text-align:center;line-height:1.7;color:#b8c7bf">${esc(notice.message)}<button class="primary" onclick="location.reload()" style="margin-top:20px">VOLVER A INTENTAR</button><details style="font-size:11px;margin-top:18px;overflow-wrap:anywhere;text-align:left"><summary>Ver detalle del error</summary><p style="letter-spacing:0;line-height:1.5;margin:10px 0">${esc(notice.detail.slice(0,300))}</p></details></div>`;}
